<template><div class="page"><el-card><template #header><div><h2>环境管理</h2><span class="muted">执行场景时可直接选择已维护的被测环境</span></div></template><el-table :data="store.environments"><el-table-column prop="name" label="名称"/><el-table-column prop="key" label="标识"/><el-table-column prop="baseUrl" label="访问地址" min-width="280"/><el-table-column prop="username" label="账号"/><el-table-column label="默认"><template #default="{row}"><el-tag v-if="row.isDefault" type="success">默认</el-tag></template></el-table-column></el-table><el-divider/><el-form v-if="store.user.role==='admin'" :model="form" label-position="top" class="settings-form"><h3>新增环境</h3><div class="config-grid"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="标识"><el-input v-model="form.key"/></el-form-item></div><el-form-item label="访问地址"><el-input v-model="form.baseUrl"/></el-form-item><div class="config-grid"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password/></el-form-item></div><el-checkbox v-model="form.isDefault">设为默认环境</el-checkbox><br><el-button type="primary" @click="save">保存环境</el-button></el-form></el-card></div></template>
<script setup>import{reactive}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{usePlatformStore}from'../stores/platform';const store=usePlatformStore(),form=reactive({name:'',key:'',baseUrl:'',username:'',password:'',isDefault:false});async function save(){await api('/api/environments',{method:'POST',body:JSON.stringify(form)});await store.loadCatalog();ElMessage.success('环境已保存')}</script>
